package main
​
import (
    "bufio"
    "fmt"
    "os"
    "sort"
    "strconv"
    "strings"
)
​
// 定义Record结构体，用于存储打卡记录
type Record struct {
    id                   string
    time                 int
    distance             int
    actualDeviceNumber   string
    registeredDeviceNumber string
    idx                  int
}
​
// 通用split函数
func split(s, delimiter string) []string {
    return strings.Split(s, delimiter)
}
​
// 判断是否异常打卡
func isNormal(r1, r2 Record) bool {
    // 时间间隔少于60s且距离相隔大于5
    return abs(r1.time-r2.time) < 60 && abs(r1.distance-r2.distance) > 5
}
​
func main() {
    scanner := bufio.NewScanner(os.Stdin)
    scanner.Scan()
    n, _ := strconv.Atoi(scanner.Text()) // 读取记录数
    normaIndex := make(map[int]bool)    // 保存异常打卡的下标
    idRecordMp := make(map[string][]Record) // 按id分组存储打卡记录
    ans := make([]string, n)            // 存储原始输入
    records := make([]Record, n)        // 存储所有记录
​
    for i := 0; i < n; i++ {
        scanner.Scan()
        s := scanner.Text()
        ans[i] = s
        tmp := split(s, ",")
        id := tmp[0]
        time, _ := strconv.Atoi(tmp[1])
        distance, _ := strconv.Atoi(tmp[2])
        actualDeviceNumber := tmp[3]
        registeredDeviceNumber := tmp[4]
        record := Record{id, time, distance, actualDeviceNumber, registeredDeviceNumber, i}
        idRecordMp[id] = append(idRecordMp[id], record)
        records[i] = record
    }
​
    // 检查异常打卡
    for i := 0; i < n; i++ {
        record := records[i]
        // 设备编号异常
        if record.actualDeviceNumber != record.registeredDeviceNumber {
            normaIndex[i] = true
        }
        // 时间距离打卡异常
        for _, r1 := range idRecordMp[record.id] {
            if isNormal(record, r1) {
                normaIndex[r1.idx] = true
                normaIndex[i] = true
            }
        }
    }
​
    // 输出结果
    if len(normaIndex) == 0 {
        fmt.Println("null")
    } else {
        // 对下标排序
        var sortedIndex []int
        for x := range normaIndex {
            sortedIndex = append(sortedIndex, x)
        }
        sort.Ints(sortedIndex)
        result := make([]string, len(sortedIndex))
        for i, x := range sortedIndex {
            result[i] = ans[x]
        }
        fmt.Println(strings.Join(result, ";"))
    }
}
